    return false;
};

input.newString:
let rest = self.locator.after(line_end);
let mut end_offset = None;
let mut last_end_offset = None;
let mut lines = UniversalNewlineIterator::with_offset(rest, line_end);

while let Some(line) = lines.next() {
    let line_text = line.as_str();
    let Some(content) = script_line_content(line_text) else {
        break;
    };

    if content == "///" {
        last_end_offset = Some(line.start() + line.as_full_str().text_len());

        // > Precedence for an ending line # /// is given when the next line is not a valid
        // > embedded content line as described above.
        // > For example, the following is a single fully valid block:
        // > ```python
        // > # /// some-toml
        // > # embedded-csharp = """
        // > # /// <summary>
        // > # /// text
        // > # ///
        // > # /// </summary>
        // > # public class MyClass { }
        // > # """
        // > # ///
        // ````
        if lines
            .next()
            .is_some_and(|next_line| is_valid_script_line(next_line.as_str()))
        {
            continue;
        }
        end_offset = last_end_offset;
        break;
    }
}

// > Unclosed blocks MUST be ignored.
//
// If the block is directly followed by a normal comment block, the closing
// tag is followed by valid script lines, so the precedence rule above never
// identifies an end tag. In that case, fall back to the most recent closing
// tag seen, which belongs to the script block rather than the normal block.
let Some(end_offset) = end_offset.or(last_end_offset) else {
    return false;
};

